"""
promo_engine.py - Superstore, Phase 4

Put this file in the same folder as your app, then:

    from promo_engine import run_promotions

    result = run_promotions(
        store="Houston, Texas",
        promotions=[
            {"sub_category": "Binders", "discount": 0.10, "start_month": 3, "end_month": 5},
            {"category": "Technology", "discount": 0.05, "start_month": 11, "end_month": 12},
        ],
    )
    print(result["score"], result["sales_increase_pct"], result["profit_increase_pct"])

Each promotion targets ONE of: "category", "sub_category" or "product" (a Product ID),
plus "discount" (0.10 = 10% off), "start_month" and "end_month" (1 to 12, the year is 2020).

Dropdown lists for your interface:
    get_options(store)                    -> {"stores", "categories", "sub_categories", "products",
                                              "months", "discounts", "targets"} - fill your dropdowns with it
    run_one(store, target_type, target, discount, start_month, end_month)
                                          -> test a single promotion quickly

Other helpers:
    list_stores()                         -> stores you can use
    baseline(store)                       -> what 2020 looks like with no promotion
    list_products(store, contains="")     -> product IDs and names to target
    run_promotions(...)                   -> sales, profit, score (see keys below)

Rules: discount up to 40%, up to 5 promotions, and the total promotion cost must stay
within the store budget (6% of its baseline sales). The result is always the same for the
same inputs.
"""
import base64, hashlib, json, math, random, zlib

# ----------------------------------------------------------------------------------------
# Rules of the game
# ----------------------------------------------------------------------------------------
MAX_DISCOUNT = 0.40
MAX_PROMOTIONS = 5
BUDGET_PCT = 0.06          # promotion budget = 6% of the store's baseline sales
PULL_FORWARD = 0.20        # share of the extra units borrowed from the next two months
FATIGUE = 0.92             # each extra month of the same promotion is a bit less effective
NOISE_SD = 0.08            # small random variation, fixed for a given store

# Maximum extra demand for a deep discount, by sub-category (1.0 = demand can double)
_SUB_A = {
    "Art": 1.3, "Binders": 1.4, "Envelopes": 1.2, "Fasteners": 1.2, "Labels": 1.3, "Paper": 1.3,
    "Storage": 1.0, "Supplies": 0.9, "Accessories": 1.1, "Phones": 1.0, "Appliances": 0.8,
    "Bookcases": 0.9, "Chairs": 0.9, "Furnishings": 1.1, "Tables": 0.6, "Copiers": 0.4, "Machines": 0.5,
}
# 2020 baseline = the 2019 pattern continued: (sales growth, profit factor)
_TREND = {
    "New York City, New York": (0.12, 1.14), "Los Angeles, California": (0.10, 1.11),
    "Detroit, Michigan": (0.15, 1.16), "Seattle, Washington": (0.00, 1.00),
    "San Diego, California": (0.00, 1.00), "San Francisco, California": (-0.08, 0.90),
    "Philadelphia, Pennsylvania": (-0.10, 1.08), "Houston, Texas": (-0.12, 1.10),
    "Chicago, Illinois": (-0.10, 1.10), "Dallas, Texas": (-0.09, 1.10),
}
_DEFAULT_TREND = (0.03, 1.03)
# How strongly each store's customers react to promotions (1.0 = average).
_STORE_BOOST = {'New York City, New York': 1.38, 'Los Angeles, California': 1.09, 'Detroit, Michigan': 0.98, 'Seattle, Washington': 1.07, 'San Diego, California': 1.35, 'San Francisco, California': 0.96, 'Philadelphia, Pennsylvania': 2.49, 'Houston, Texas': 1.27, 'Chicago, Illinois': 2.11, 'Dallas, Texas': 1.63}

