_cache = {}


def _load():
    if "d" not in _cache:
        _cache["d"] = json.loads(zlib.decompress(base64.b64decode("".join(_DATA.split()))).decode("utf-8"))
    return _cache["d"]


def _rng(*parts):
    h = hashlib.sha256("|".join(str(p) for p in parts).encode("utf-8")).hexdigest()
    return random.Random(int(h[:16], 16))


def _store_sensitivity(store):
    return (0.85 + 0.35 * _rng("sens", store).random()) * _STORE_BOOST.get(store, 1.0)


def _noise(store, sub, month):
    return math.exp(_rng("noise", store, sub, month).gauss(0, NOISE_SD))


def _match(value, options):
    v = str(value).strip().lower()
    for o in options:
        if o.lower() == v:
            return o
    return None


def list_stores():
    """Stores that can be used (City, State)."""
    return sorted(_load()["rows"].keys())


def _store_rows(store):
    d = _load()
    name = _match(store, d["rows"].keys())
    if name is None:
        return None, None
    g, pf = _TREND.get(name, _DEFAULT_TREND)
    prods = d["products"]
    raw = d["rows"][name]
    s_tot = sum(r[3] for r in raw) * (1 + g)
    p0_tot = sum(r[4] for r in raw) * (1 + g)
    c_tot = s_tot - p0_tot
    p_target = sum(r[4] for r in raw) * pf
    # Profit trend: a falling profit deepens the rows that already lose money;
    # a rising profit lowers costs evenly.
    deficit = p0_tot - p_target
    neg_tot = sum(-r[4] * (1 + g) for r in raw if r[4] < 0)
    if deficit > 0 and neg_tot > 0:
        kappa, extra_share = 1.0, deficit / neg_tot
    else:
        kappa = (s_tot - p_target) / c_tot if c_tot > 0 else 1.0
        kappa, extra_share = min(1.6, max(0.5, kappa)), 0.0
    rows = []
    for pid, month, u, s, p in raw:
        U = u * (1 + g)
        S = s * (1 + g)
        C = (S - p * (1 + g)) * kappa
        if p < 0 and extra_share:
            C += -p * (1 + g) * extra_share
        if U <= 0 or S <= 0:
            continue
        pname, cat, sub = prods[pid]
        rows.append({"pid": pid, "name": pname, "cat": cat, "sub": sub, "month": month,
                     "U": U, "price": S / U, "ucost": C / U})
    return name, rows


def _totals(rows):
    S = sum(r["U"] * r["price"] for r in rows)
    P = sum(r["U"] * (r["price"] - r["ucost"]) for r in rows)
    return S, P


def baseline(store):
    """2020 with no promotion: sales, profit and the promotion budget for this store."""
    name, rows = _store_rows(store)
    if name is None:
        return {"ok": False, "errors": [f"Unknown store '{store}'. Use list_stores()."]}
    S, P = _totals(rows)
    subs = {}
    for r in rows:
        a = subs.setdefault(r["sub"], {"sub_category": r["sub"], "category": r["cat"], "sales": 0.0, "profit": 0.0, "units": 0.0})
        a["sales"] += r["U"] * r["price"]; a["profit"] += r["U"] * (r["price"] - r["ucost"]); a["units"] += r["U"]
    return {"ok": True, "store": name, "baseline_sales": round(S, 2), "baseline_profit": round(P, 2),
            "budget_limit": round(S * BUDGET_PCT, 2),
            "by_sub_category": sorted([{k: (round(v, 2) if isinstance(v, float) else v) for k, v in a.items()} for a in subs.values()],
                                      key=lambda x: -x["sales"])}


def list_products(store, contains="", top=50):
    """Products sold by this store (ID, name, sub-category), biggest sellers first."""
    name, rows = _store_rows(store)
    if name is None:
        return []
    agg = {}
    for r in rows:
        a = agg.setdefault(r["pid"], {"product_id": r["pid"], "name": r["name"], "category": r["cat"], "sub_category": r["sub"], "baseline_sales": 0.0})
        a["baseline_sales"] += r["U"] * r["price"]
    out = [a for a in agg.values() if contains.lower() in a["name"].lower() or contains.lower() in a["product_id"].lower()]
    out.sort(key=lambda x: -x["baseline_sales"])
    return [dict(a, baseline_sales=round(a["baseline_sales"], 2)) for a in out[:top]]


MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August",
               "September", "October", "November", "December"]
DISCOUNT_LEVELS = [0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40]


def get_options(store):
    """Everything a dropdown needs for one store.

    Returns a dict:
      stores          list of stores
      categories      ["Furniture", ...]
      sub_categories  [{"sub_category", "category"}, ...]  (filter by category for a linked dropdown)
      products        [{"product_id", "name", "label", ...}, ...]  (label = text to show in the dropdown)
      months          [{"value": 1, "label": "January"}, ...]
      discounts       [{"value": 0.05, "label": "5%"}, ...]
      targets         ["category", "sub_category", "product"]
    """
    name, rows = _store_rows(store)
    if name is None:
        return {"ok": False, "errors": [f"Unknown store '{store}'. Use list_stores()."]}
    subs = sorted({(r["sub"], r["cat"]) for r in rows})
    prods = list_products(name, top=10**6)
    for p in prods:
        p["label"] = f'{p["name"]} ({p["product_id"]})'
    return {"ok": True, "store": name, "stores": list_stores(),
            "categories": sorted({r["cat"] for r in rows}),
            "sub_categories": [{"sub_category": s, "category": c} for s, c in subs],
            "products": prods,
            "months": [{"value": i + 1, "label": m} for i, m in enumerate(MONTH_NAMES)],
            "discounts": [{"value": d, "label": f"{round(d * 100)}%"} for d in DISCOUNT_LEVELS],
            "targets": ["category", "sub_category", "product"]}


def run_one(store, target_type, target, discount, start_month, end_month):
    """Test ONE promotion. target_type is 'category', 'sub_category' or 'product'
    (target = the name, or the Product ID). Same result dictionary as run_promotions."""
    return run_promotions(store, [{target_type: target, "discount": discount,
                                   "start_month": start_month, "end_month": end_month}])


def _parse(promotions, rows):
    errors, parsed = [], []
    cats = sorted({r["cat"] for r in rows}); subs = sorted({r["sub"] for r in rows}); pids = sorted({r["pid"] for r in rows})
    if not isinstance(promotions, (list, tuple)):
        return [], ["'promotions' must be a list of dictionaries."]
    if len(promotions) > MAX_PROMOTIONS:
        errors.append(f"Too many promotions ({len(promotions)}). Maximum is {MAX_PROMOTIONS}.")
    for i, p in enumerate(promotions, 1):
        tag = f"Promotion {i}: "
        scopes = [k for k in ("category", "sub_category", "product") if p.get(k) not in (None, "")]
        if len(scopes) != 1:
            errors.append(tag + "give exactly one of 'category', 'sub_category' or 'product'."); continue
        scope = scopes[0]
        options = {"category": cats, "sub_category": subs, "product": pids}[scope]
        val = _match(p[scope], options)
        if val is None:
            errors.append(tag + f"unknown {scope} '{p[scope]}' for this store." + (f" Valid values: {', '.join(options)}." if scope != "product" else " Use list_products(store)."))
            continue
        try:
            d = float(p.get("discount"))
        except (TypeError, ValueError):
            errors.append(tag + "'discount' is missing or not a number (use 0.10 for 10%)."); continue
        if d <= 0 or d > MAX_DISCOUNT:
            errors.append(tag + f"discount {d} must be above 0 and at most {MAX_DISCOUNT} (use 0.10 for 10%)."); continue
        try:
            a, b = int(p.get("start_month")), int(p.get("end_month"))
        except (TypeError, ValueError):
            errors.append(tag + "'start_month' and 'end_month' must be numbers from 1 to 12."); continue
        if not (1 <= a <= b <= 12):
            errors.append(tag + "months must satisfy 1 <= start_month <= end_month <= 12."); continue
        parsed.append({"scope": scope, "value": val, "d": d, "a": a, "b": b})
    return parsed, errors


def run_promotions(store, promotions):
    """Apply promotions to a store's 2020 baseline and return the results.

    Keys of the returned dictionary: ok, errors, store, baseline_sales, baseline_profit,
    new_sales, new_profit, sales_increase_pct, profit_increase_pct, score,
    budget_used, budget_limit, by_sub_category, by_month.
    """
    name, rows = _store_rows(store)
    if name is None:
        return {"ok": False, "errors": [f"Unknown store '{store}'. Use list_stores()."]}
    parsed, errors = _parse(promotions, rows)
    base_S, base_P = _totals(rows)
    budget_limit = base_S * BUDGET_PCT
    if errors:
        return {"ok": False, "errors": errors, "store": name, "budget_limit": round(budget_limit, 2)}
    sens = _store_sensitivity(name)

    # pass 1: best promotion per product-month, extra demand
    res = []
    pull = {}
    for r in rows:
        best = None
        for p in parsed:
            if not (p["a"] <= r["month"] <= p["b"]): continue
            if (p["scope"] == "category" and r["cat"] != p["value"]) or (p["scope"] == "sub_category" and r["sub"] != p["value"]) or (p["scope"] == "product" and r["pid"] != p["value"]):
                continue
            if best is None or p["d"] > best["d"]: best = p
        d, k, up, end = 0.0, 1, 0.0, 0
        if best:
            d = best["d"]; k = r["month"] - best["a"] + 1; end = best["b"]
            up = _SUB_A.get(r["sub"], 1.0) * sens * (1 - math.exp(-d / 0.12)) * (FATIGUE ** (k - 1)) * _noise(name, r["sub"], r["month"])
        u_new = r["U"] * (1 + up)
        res.append([r, d, u_new])
        if best:
            key = (r["sub"], end)
            pull[key] = pull.get(key, 0.0) + (u_new - r["U"]) * PULL_FORWARD

    # pass 2: borrowed demand removed from the following two months (December absorbs any overflow)
    base_units = {}
    for r in rows:
        base_units[(r["sub"], r["month"])] = base_units.get((r["sub"], r["month"]), 0.0) + r["U"]
    ded = {}
    for (sub, end), units in pull.items():
        for m in (end + 1, end + 2):
            ded[(sub, min(m, 12))] = ded.get((sub, min(m, 12)), 0.0) + units / 2
    frac = {k: min(0.5, v / base_units[k]) for k, v in ded.items() if base_units.get(k, 0) > 0}

    # pass 3: results
    new_S = new_P = used = 0.0
    sub_acc, mon_acc = {}, {}
    for r, d, u_new in res:
        u = u_new * (1 - frac.get((r["sub"], r["month"]), 0.0))
        price = r["price"] * (1 - d)
        S = u * price; P = u * (price - r["ucost"]); used += d * r["price"] * u
        new_S += S; new_P += P
        bS, bP = r["U"] * r["price"], r["U"] * (r["price"] - r["ucost"])
        a = sub_acc.setdefault(r["sub"], {"sub_category": r["sub"], "category": r["cat"], "baseline_sales": 0.0, "new_sales": 0.0, "baseline_profit": 0.0, "new_profit": 0.0})
        a["baseline_sales"] += bS; a["new_sales"] += S; a["baseline_profit"] += bP; a["new_profit"] += P
        m = mon_acc.setdefault(r["month"], {"month": r["month"], "baseline_sales": 0.0, "new_sales": 0.0, "baseline_profit": 0.0, "new_profit": 0.0})
        m["baseline_sales"] += bS; m["new_sales"] += S; m["baseline_profit"] += bP; m["new_profit"] += P

    rnd = lambda x: round(x, 2) + 0.0
    if used > budget_limit + 1e-9:
        return {"ok": False, "store": name, "budget_used": rnd(used), "budget_limit": rnd(budget_limit),
                "errors": [f"Promotion cost {rnd(used)} is above the store budget {rnd(budget_limit)}. Reduce the discounts, the period or the number of promotions."]}
    s_pct = (new_S / base_S - 1) * 100
    p_pct = (new_P - base_P) / abs(base_P) * 100 if base_P else 0.0
    score = 0.5 * s_pct + 0.5 * max(-100.0, min(100.0, p_pct))
    return {"ok": True, "errors": [], "store": name,
            "baseline_sales": rnd(base_S), "baseline_profit": rnd(base_P),
            "new_sales": rnd(new_S), "new_profit": rnd(new_P),
            "sales_increase_pct": rnd(s_pct), "profit_increase_pct": rnd(p_pct), "score": rnd(score),
            "budget_used": rnd(used), "budget_limit": rnd(budget_limit),
            "by_sub_category": [{k: (rnd(v) if isinstance(v, float) else v) for k, v in a.items()} for a in sorted(sub_acc.values(), key=lambda x: -x["baseline_sales"])],
            "by_month": [{k: (rnd(v) if isinstance(v, float) else v) for k, v in sorted(mon_acc.items())[i][1].items()} for i in range(len(mon_acc))]}


if __name__ == "__main__":
    print(list_stores()[:5], "...")
    print(baseline("Houston, Texas")["baseline_sales"])